function okUrl(u){return /^https?:\/\//i.test(u||'')?u:'';}
var MEDIA=null;function loadMedia(){if(MEDIA||loadMedia._r)return;loadMedia._r=1;fetch('/assets/media/media.json').then(function(r){return r.ok?r.json():{};}).then(function(d){MEDIA=d;var c=cur();if(c==='spot'||c==='map'||c==='home')rerender();}).catch(function(){MEDIA={};});}
