condCard=function(){var L=state.userLogs||[],last=L.filter(function(l){return l.date;}).sort(function(a,b){return a.date<b.date?1:-1;})[0];
  var since=last?Math.round((Date.now()-new Date(last.date+'T12:00:00'))/36e5):null;
  return '<div class="cond"><div class="row"><b>오늘의 컨디션</b><span>기기 연결 전</span></div><div class="mgrid"><div><small>수면 · 심박</small><b style="font-size:15px">연결 필요</b><em class="m">Garmin · Apple 건강</em></div><div><small>마지막 다이브 후</small><b>'+(since!=null?(since<72?since+'시간':Math.round(since/24)+'일'):'—')+'</b><em class="c">'+(last?'내 로그 기준':'로그가 없어요')+'</em></div><div><small>비행 전 대기</small><b>'+(since!=null&&since<18?(18-since)+'시간 더':'지남')+'</b><em class="c">여러 번 다이빙 기준 18시간</em></div></div><a class="btn btn-line" href="#devices" style="margin-top:10px;width:100%;background:transparent;color:inherit;border-color:currentColor">기기 연결하기</a></div>';};

