V.devices=function(){setTitle('기기 연결');return '<div class="vh"><div><a class="small" href="#log">← 로그</a><h1>기기 연결</h1><p>지금 되는 것과 준비 중인 것</p></div></div><div class="panel"><div class="list">'+item({tags:[['지금 가능','ok']],t:'UDDF · Subsurface 파일',s:'Shearwater Cloud, Subsurface, Suunto DM5, MacDive에서 내보낸 파일을 로그 화면에서 가져와요',r:'<a href="#log">가져오기</a>'})+item({tags:[['준비 중','gray']],t:'Garmin Connect (수면 · 심박 · Descent 로그)',s:'Garmin 개발자 프로그램 승인 뒤 열려요'})+item({tags:[['준비 중','gray']],t:'Apple 건강 · Apple Watch Ultra 수심',s:'iOS 앱이 나와야 연결할 수 있어요'})+item({tags:[['준비 중','gray']],t:'Shearwater 블루투스 직접 연결',s:'앱 버전에서 지원할 예정이에요'})+'</div><p class="small" style="margin:10px 0 0">건강 정보는 가입할 때 선택 동의한 경우에만, 컨디션 카드를 보여주는 데만 써요.</p></div>';};
function parseDiveXml(txt,name){var doc=new DOMParser().parseFromString(txt,'application/xml'),out=[];if(doc.querySelector('parsererror'))return out;
  var dives=doc.getElementsByTagName('dive');[].forEach.call(dives,function(d){var o={src:'파일'};
    var dt=d.getAttribute('date')||(d.getElementsByTagName('datetime')[0]||{}).textContent||'';o.date=String(dt).slice(0,10);
    var dur=d.getAttribute('duration');if(dur){var m=dur.match(/(\d+):(\d+)/);if(m)o.time=+m[1]+Math.round(+m[2]/60);}
    var dc=d.getElementsByTagName('divecomputer')[0],depthEl=dc&&dc.getElementsByTagName('depth')[0];if(depthEl&&depthEl.getAttribute('max'))o.depth=parseFloat(depthEl.getAttribute('max'));
    var gm=d.getElementsByTagName('greatestdepth')[0];if(gm)o.depth=parseFloat(gm.textContent);var dt2=d.getElementsByTagName('diveduration')[0];if(dt2)o.time=Math.round(parseFloat(dt2.textContent)/60);
    if(!o.depth){var mx=0;[].forEach.call(d.getElementsByTagName('depth'),function(e){var v=parseFloat(e.textContent);if(v>mx)mx=v;});if(mx)o.depth=mx;}
    var site=d.getAttribute('divesiteid');if(site){var ds=doc.querySelector('site[uuid="'+site+'"]');if(ds)o.site=ds.getAttribute('name');}
    var lk=d.getElementsByTagName('link')[0];if(lk&&!o.site){var sid=lk.getAttribute('ref'),se=sid&&doc.querySelector('site[id="'+sid+'"]'),nm=se&&se.getElementsByTagName('name')[0];if(nm)o.site=nm.textContent;}
    if(o.depth)o.depth=Math.round(o.depth*10)/10;if(o.date||o.depth)out.push(o);});return out;}

