  var cb=document.getElementById('csvBtn');if(cb)cb.onclick=function(){var rows=[['날짜','포인트','최대수심(m)','시간(분)','출처']].concat((state.userLogs||[]).map(function(l){return [l.date||'',l.site||'',l.depth||'',l.time||'',l.src||''];}));var csv='﻿'+rows.map(function(r){return r.map(function(c){return '"'+String(c).replace(/"/g,'""')+'"';}).join(',');}).join('\n');var u=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),a=document.createElement('a');a.href=u;a.download='dive-logs.csv';a.click();setTimeout(function(){URL.revokeObjectURL(u);},2000);};
  var rb=document.getElementById('resendBtn');if(rb)rb.onclick=function(){rb.disabled=true;BE.sb.auth.resend({type:'signup',email:state.pendingEmail,options:{emailRedirectTo:location.origin+'/'}}).then(function(r){document.getElementById('resendMsg').textContent=r.error?(/rate|seconds/i.test(r.error.message)?'잠시 뒤 다시 보낼 수 있어요.':'보내지 못했어요: '+r.error.message):'다시 보냈어요.';setTimeout(function(){rb.disabled=false;},30000);});};
  main.querySelectorAll('[data-mcat]').forEach(function(b){b.onclick=function(){state.mcat=b.dataset.mcat;rerender();};});
  main.querySelectorAll('[data-resubmit]').forEach(function(b){b.onclick=function(){b.disabled=true;BE.sb.from('businesses').update({status:'pending'}).eq('id',+b.dataset.resubmit).then(function(r){toast(r.error?'보내지 못했어요.':'다시 심사를 신청했어요.');BE.pull();});};});
  var aq=document.getElementById('admQ');if(aq)aq.oninput=function(){clearTimeout(aq._t);aq._t=setTimeout(function(){state.adm.q=aq.value.trim();rerender();var n=document.getElementById('admQ');if(n){n.focus();n.setSelectionRange(n.value.length,n.value.length);}},300);};
  main.querySelectorAll('[data-inqdone]').forEach(function(b){b.onclick=function(){var x=state.adm.inq.filter(function(y){return y.id==b.dataset.inqdone;})[0];BE.sb.from('partner_inquiries').update({handled:!x.handled}).eq('id',x.id).then(function(r){if(!r.error){x.handled=!x.handled;rerender();}});};});
  main.querySelectorAll('[data-repdone]').forEach(function(b){b.onclick=function(){BE.sb.from('reports').update({status:b.dataset.st}).eq('id',+b.dataset.repdone).then(function(){BE.sb.from('admin_log').insert({action:'report:'+b.dataset.st,target:'report#'+b.dataset.repdone});state.adm.rep=null;state.adm.repReq=0;rerender();});};});
  main.querySelectorAll('[data-repdel]').forEach(function(b){b.onclick=function(){if(!confirm('이 글을 내릴까요?'))return;var t=b.dataset.repdel==='post'?'posts':'comments';BE.sb.from(t).delete().eq('id',+b.dataset.tid).then(function(r){if(r.error)return toast('내리지 못했어요. 게시물은 작성자만 지울 수 있게 되어 있어 운영자 삭제 권한을 열어야 해요.');return BE.sb.from('reports').update({status:'done'}).eq('id',+b.dataset.rid).then(function(){BE.sb.from('admin_log').insert({action:'takedown',target:b.dataset.repdel+'#'+b.dataset.tid});state.adm.rep=null;state.adm.repReq=0;toast('내렸어요.');rerender();});});};});
